#include "../ring3_common.hpp"
static constexpr u32 W=640,H=480;static u32*pix;static u64 events,win;static bool dirty=true;static int page=0;
static void rr(i32 x,i32 y,i32 w,i32 h,i32 r,u32 c){rect(pix,W,H,x+r,y,w-2*r,h,c);rect(pix,W,H,x,y+r,w,h-2*r,c);for(i32 yy=0;yy<r;yy++)for(i32 xx=0;xx<r;xx++){i32 dx=r-xx-1,dy=r-yy-1;if(dx*dx+dy*dy<=r*r){rect(pix,W,H,x+xx,y+yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+yy,1,1,c);rect(pix,W,H,x+xx,y+h-1-yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+h-1-yy,1,1,c);}}}
static const char* cats[]={"SYSTEM","KEYBOARD / MOUSE","AUDIO","DISPLAY / VISUAL","NETWORK / WI-FI","PRINTERS","USER PROFILES","STORAGE","SECURITY","ACCESSIBILITY"};
static void draw(){fill(pix,W*H,0x00f3f6f9);rect(pix,W,H,0,0,W,58,0x00ffffff);text(pix,W,H,24,20,"SETTINGS",0x001f2933,2);rr(188,14,W-214,34,17,0x00edf1f5);text(pix,W,H,208,27,"FIND A SETTING",0x00636f7b,1);rect(pix,W,H,0,58,230,H-58,0x00e9eef4);for(int i=0;i<10;i++){if(i==page)rr(12,74+i*39,206,32,9,0x00ffffff);text(pix,W,H,28,86+i*39,cats[i],i==page?0x001a5fa8:0x003f4a55,1);}text(pix,W,H,264,86,cats[page],0x001f2933,2);rr(264,122,464,82,14,0x00ffffff);rr(264,220,464,82,14,0x00ffffff);rr(264,318,464,82,14,0x00ffffff);const char*a="DEVICE AND PREFERENCE CONTROLS";const char*b="STATUS / DIAGNOSTICS";const char*c="ADVANCED OPTIONS";if(page==1){a="POINTER SPEED / BUTTONS / SCROLL";b="KEYBOARD LAYOUT / REPEAT / SHORTCUTS";c="INPUT DEVICE STATUS";}else if(page==2){a="OUTPUT DEVICE / MASTER VOLUME";b="APPLICATION VOLUME / TEST AUDIO";c="AUDIO DRIVER STATUS";}else if(page==3){a="RESOLUTION / SCALE / THEME";b="WINDOWS / ANIMATION / CONTRAST";c="GRAPHICS DRIVER STATUS";}else if(page==4){a="WI-FI / ETHERNET / ROUTER";b="IP / DNS / FIREWALL";c="NETWORK DRIVER STATUS";}else if(page==5){a="ADD PRINTER / DEFAULT PRINTER";b="QUEUE / PAPER / QUALITY";c="PRINT SERVICE STATUS";}else if(page==6){a="PROFILE / PASSWORD / PICTURE";b="PERMISSIONS / SIGN-IN";c="ADD OR REMOVE USER";}text(pix,W,H,286,148,a,0x00293642,1);text(pix,W,H,286,246,b,0x00293642,1);text(pix,W,H,286,344,c,0x00293642,1);text(pix,W,H,264,H-36,"RING 3 SETTINGS - PRIVILEGED CHANGES REQUIRE MEDIATED SERVICES",0x00636f7b,1);sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,170,80);if(!win)sc(0,2);for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==POINTER&&m.bytes==sizeof(PtrEv)){auto*p=(PtrEv*)m.payload;if((p->flags&1)&&p->x<230&&p->y>=74){int q=(p->y-74)/39;if(q>=0&&q<10){page=q;dirty=true;}}}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
